import { useEffect, useState } from 'react'
import fixture from '../fixtures/synthetic-tracer.json'
import { resolveSimulatedLaunch } from '../domain/launch-controller.mjs'
import { evaluateAcknowledgement } from '../domain/review-controller.mjs'
import { evaluateFollowUpDirection, evaluateT08Verification } from '../domain/direction-controller.mjs'
import { recordReferralRoute } from '../domain/referral-controller.mjs'
