import { JourneyRail, WorkflowStatus } from '../components/WorkflowContext'

function screenFromHash(): ScreenId { return resolveScreenId(window.location.hash.replace('#', '') || 'start') }
function normalizeHash(screenId: ScreenId) { const normalizedHash = `#${routeForScreen(screenId)}`; if (window.location.hash !== normalizedHash) window.history.replaceState(null, '', normalizedHash) }
function navigateTo(screenId: ScreenId) { window.location.hash = routeForScreen(screenId) }

function Launch({ status, onLaunch }: { status: 'ready' | 'loading'; onLaunch: (outcome?: 'authorised' | 'unavailable') => void }) {
  const loading = status === 'loading'
  return <section className="content-card"><p className="eyebrow">SCR-01 · COS-601 · simulated SMART launch</p><h2>Open the diagnostic closure workspace</h2><p>Use the Clinic physician profile to open the linked episode. No patient information appears until the access check passes.</p><WorkflowStatus state={loading ? 'Launch, authorisation and retrieval in progress' : 'Ready — no protected context retrieved'} owner="Clinic physician · access support handles blocked launch" next={loading ? 'Wait for the simulated access outcome' : 'Open workspace'} /><div className="action-group"><button className="primary-action" disabled={loading} id="simulated-launch-trigger" type="button" onClick={() => onLaunch()}>{loading ? 'Checking simulated access…' : 'Open workspace'}</button><button className="secondary-action" disabled={loading} type="button" onClick={() => onLaunch('unavailable')}>Troubleshoot access</button></div><aside className="home-guidance" aria-labelledby="home-guidance-title"><div><p className="panel-label">Before you begin</p><h3 id="home-guidance-title">Start with secure episode access</h3></div><ol><li><strong>Open the workspace</strong><span>Run the access check before episode information is shown.</span></li><li><strong>Review assigned work</strong><span>Check the source evidence before recording a decision.</span></li><li><strong>Resolve blocked work safely</strong><span>Use Exceptions when required evidence or access is unavailable.</span></li></ol></aside></section>
}

function Workspace({ authorised, onException, onViewNext }: { authorised: boolean; onException: () => void; onViewNext: () => void }) {
  if (!authorised) return <section className="content-card"><p className="eyebrow">SCR-02 · protected context gate</p><h2>Authorised context is required</h2><p>The workspace stays hidden until simulated launch and verified linkage pass.</p><button className="secondary-action" type="button" onClick={onException}>View safe access-recovery route</button></section>
  const report = fixture.diagnosticReports[0]
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-02 · COS-602 · read-only episode orientation</p><h2>Asha Mehta</h2><p>Episode SYN-EP-8001 · Encounter SYN-ENC-2001 · verified linkage</p></div><span className="state-badge">Diagnostic Completed</span></header><div className="screen-grid"><div><WorkflowStatus state="Diagnostic Completed" owner="Care Coordinator · read-only episode orientation" next="Assigned Clinic physician reviews the current report" ageDue="Review timing begins when the task is assigned." /><section className="evidence-panel orientation-context"><p className="panel-label">Episode summary</p><h3>Diagnostic episode</h3><dl><div><dt>Episode status</dt><dd>Diagnostic work is complete and report evidence is available.</dd></div><div><dt>Source</dt><dd>Verified launch context and approved episode evidence.</dd></div><div><dt>Coordinator</dt><dd>Care Coordinator</dd></div><div><dt>Next owner</dt><dd>Assigned Clinic physician</dd></div></dl></section><section className="milestones"><h3>Workflow evidence</h3><ol><li><strong>Order created</strong><span>ServiceRequest SYN-SR-4001 · read-only source record</span></li><li><strong>Diagnostic completed</strong><span>Operational completion evidence remains separate from result availability</span></li><li><strong>Result availability</strong><span>{report.id} v{report.version} · shown only after fixture-specific T04 validation</span></li></ol></section><div className="status-panel"><strong>Read-only overview</strong><span>The assigned Clinic physician owns the next report-review task.</span></div><section className="viewer-navigation-panel" aria-labelledby="viewer-navigation-title"><p className="panel-label">Portfolio walkthrough</p><h3 id="viewer-navigation-title">Continue the case walkthrough</h3><p id="viewer-navigation-boundary">Opens result review for this case. No workflow action is recorded.</p><button aria-describedby="viewer-navigation-boundary" className="secondary-action" type="button" onClick={onViewNext}>Open result review</button></section></div><JourneyRail phase="Diagnostic progress" next="The assigned Clinic physician owns the next represented result-review task." /></div></section>
}

function ReviewScreen({ onException, onViewNext }: { onException: (condition: string) => void; onViewNext: () => void }) {
  const [acknowledgedAt, setAcknowledgedAt] = useState<string | null>(null)
  const assignment = fixture.reviewAssignment
  const report = fixture.diagnosticReports.find((item) => item.version === assignment.reportVersion)!
  const acknowledgementAudit = getAuditEntries().find((entry) => entry.event === 'EVT-10 result.acknowledgement.recorded')!
  const outcome = evaluateAcknowledgement(fixture, { actorRef: assignment.assignedTo, reportVersion: assignment.reportVersion, currentState: assignment.state, acknowledgementId: 'SYN-ACK-602-01' })
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-03 · COS-603 · result review</p><h2>Review diagnostic report</h2><p>Asha Mehta · SYNTHETIC CASE · source report remains read-only</p></div><span className="state-badge">{acknowledgedAt ? 'Result Acknowledged' : assignment.state}</span></header><div className="screen-grid"><div><WorkflowStatus state={acknowledgedAt ? 'Result Acknowledged' : assignment.state} owner="Synthetic Clinic Physician · assigned reviewer" next={acknowledgedAt ? 'Follow-up Decision Required — represented on SCR-04' : 'Review the report, then acknowledge the current version'} ageDue={`Assigned task due ${assignment.dueAt}`} /><section className="evidence-panel review-source-panel"><p className="panel-label">Read-only source report</p><h3>{report.id} · current v{report.version}</h3><dl><div><dt>Source status</dt><dd>{report.status} · current version</dd></div><div><dt>Issued</dt><dd>{report.issuedAt}</dd></div><div><dt>Assigned reviewer</dt><dd>Synthetic Clinic Physician · {assignment.assignedRole}</dd></div><div><dt>Order link</dt><dd>{report.basedOn}</dd></div><div><dt>Supporting evidence</dt><dd>{report.resultRefs.join(', ')}</dd></div></dl></section><section className="evidence-panel acknowledgement-panel" aria-labelledby="acknowledgement-boundary-title"><p className="panel-label">Human acknowledgement boundary</p><h3 id="acknowledgement-boundary-title">Acknowledge this exact source version</h3><p>Acknowledgement records that the assigned Clinic physician reviewed this exact source version. It does not diagnose, approve a referral or select the follow-up direction.</p>{acknowledgedAt ? <><div className="status-panel" role="status"><strong>Acknowledgement recorded for current report version {report.version}</strong><span>Actor: {acknowledgementAudit.actor} · recorded at {acknowledgedAt} · {acknowledgementAudit.event}.</span></div><section className="viewer-navigation-panel" aria-labelledby="review-viewer-navigation-title"><p className="panel-label">Portfolio walkthrough</p><h3 id="review-viewer-navigation-title">Continue to follow-up planning</h3><p id="review-viewer-navigation-boundary">Opens the follow-up task for this synthetic case. No workflow action is recorded.</p><button aria-describedby="review-viewer-navigation-boundary" className="secondary-action" type="button" onClick={onViewNext}>Open follow-up task</button></section></> : <div className="action-group"><button className="primary-action" type="button" onClick={() => outcome.allowed ? setAcknowledgedAt(acknowledgementAudit.timestamp) : onException(outcome.reason)}>Acknowledge current report version</button><button className="secondary-action" type="button" onClick={() => onException('Result Incomplete')}>Show incomplete-result safe route</button></div>}</section></div><JourneyRail phase="Clinical review" next="Only the assigned Clinic physician may acknowledge the current version." /></div></section>
}

type DirectionSuccess = Extract<ReturnType<typeof evaluateFollowUpDirection>, { allowed: true }>

const DIRECTION_OPTIONS = [
  { value: 'clinic management', label: 'Clinic management', consequence: 'Keeps Follow-up Decision Required until the Care Coordinator verifies the T08 owner, timeframe, next task and applicable communication evidence.' },
  { value: 'day-care referral', label: 'Day-care referral', consequence: 'Records Referral Created and makes represented referral handoff preparation available. It does not route the package or establish receiving acceptance.' },
  { value: 'hospital escalation', label: 'Hospital escalation', consequence: 'Records Referral Created and makes represented escalation handoff preparation available. It does not route the package or establish receiving acceptance.' },
] as const

function OldDirectionScreen({ onException }: { onException: (condition: string) => void }) {
  const [selectedDirection, setSelectedDirection] = useState('')
  const [evidenceReference, setEvidenceReference] = useState('')
  const [result, setResult] = useState<DirectionSuccess | null>(null)
  function recordDirection() { const outcome = evaluateFollowUpDirection({ actorRole: 'Clinic physician', currentState: 'Follow-up Decision Required', reportVersion: '2', selectedDirection, evidenceReference, directionId: 'SYN-DIR-602-01' }); if (!outcome.allowed) { onException(outcome.reason); return }; setResult(outcome) }
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-04 · COS-604 · human-owned follow-up direction</p><h2>Record a follow-up direction</h2><p>Asha Mehta · SYNTHETIC CASE · acknowledged report SYN-DR-6001 v2</p></div><span className="state-badge">{result?.stateAfter ?? 'Follow-up Decision Required'}</span></header><div className="screen-grid"><div><WorkflowStatus state={result?.stateAfter ?? 'Follow-up Decision Required'} owner="Synthetic Clinic Physician · clinical direction owner" next={result?.nextAction ?? 'Select one direction and record its evidence'} /><section className="evidence-panel"><p className="panel-label">Human decision boundary</p><h3>Clinic physician decision</h3><p>ContinuumOS records the selected direction and evidence. It does not recommend, rank or preselect a care direction.</p><fieldset className="direction-options" disabled={Boolean(result)}><legend>Select one approved direction</legend>{['clinic management', 'day-care referral', 'hospital escalation'].map((direction) => <label key={direction}><input checked={selectedDirection === direction} name="direction" type="radio" onChange={() => setSelectedDirection(direction)} />{direction}</label>)}</fieldset><label className="evidence-input">Direction rationale / evidence reference<input value={evidenceReference} onChange={(event) => setEvidenceReference(event.target.value)} placeholder="For example: SYN-DR-6001 v2" disabled={Boolean(result)} /></label>{result ? <div className="status-panel" role="status"><strong>Direction recorded: {selectedDirection}</strong><span>Actor: Synthetic Clinic Physician · report v2 · EVT-11. {result.requiresCoordinatorVerification ? 'Clinic-management T08 verification remains pending with the Care Coordinator; no confirmation is available here.' : result.nextAction}</span></div> : <div className="action-group"><button className="primary-action" type="button" onClick={recordDirection}>Record follow-up direction</button><button className="secondary-action" type="button" onClick={() => onException('Current report version requires review')}>Show stale-version safe route</button></div>}</section></div><JourneyRail phase="Human direction" next={result?.nextAction ?? 'A human Clinic physician must choose and evidence the next direction.'} /></div></section>
}

function ReferralScreen({ onException, onViewNext }: { onException: (condition: string) => void; onViewNext: () => void }) {
  const [destination, setDestination] = useState('')
  const [requiredFieldsComplete, setRequiredFieldsComplete] = useState(false)
  const [clinicalContentApplicable, setClinicalContentApplicable] = useState(true)
  const [clinicalApprovalId, setClinicalApprovalId] = useState('')
  const [routeResult, setRouteResult] = useState<Extract<ReturnType<typeof recordReferralRoute>, { allowed: true }> | null>(null)
  const packageInput = { actorRole: 'Referral Coordinator', currentState: 'Referral Created', direction: 'day-care referral', reportVersion: '2', packageId: 'SYN-RP-1001 v1', destination, requiredFieldsComplete, coordinatorApprovalId: 'SYN-RC-1001', clinicalContentApplicable, clinicalApprovalId }
  const readiness = recordReferralRoute({ ...packageInput, alreadyRouted: false, sendOutcome: 'sent' })
  const readinessMessage = readiness.allowed ? 'Referral Coordinator approval: SYN-RC-1001. Route records a send attempt only; it is not delivery or receiving acceptance.' : readiness.reason
  const routed = Boolean(routeResult)
  const routingRequirements = [
    { label: 'Approved human direction', value: 'Day-care referral · SYN-DIR-602-01', complete: true },
    { label: 'Current acknowledged report', value: 'SYN-DR-6001 v2', complete: true },
    { label: 'Package ID / version', value: 'SYN-RP-1001 v1', complete: true },
    { label: 'Destination', value: destination || 'Required before routing', complete: Boolean(destination.trim()) },
    { label: 'Required package fields', value: requiredFieldsComplete ? 'Complete and reviewed' : 'Completion evidence required', complete: requiredFieldsComplete },
    { label: 'Referral Coordinator approval', value: 'SYN-RC-1001 · approved operational package', complete: true },
    { label: 'Clinical-content approval', value: clinicalContentApplicable ? clinicalApprovalId || 'Clinic physician approval required' : 'Not applicable to this package', complete: !clinicalContentApplicable || Boolean(clinicalApprovalId.trim()) },
  ]
  function routePackage() { const outcome = recordReferralRoute({ ...packageInput, alreadyRouted: routed, sendOutcome: 'sent' }); if ('reason' in outcome) { onException(outcome.reason); return }; setRouteResult(outcome) }
  function showSendFailure() { const outcome = recordReferralRoute({ ...packageInput, alreadyRouted: false, sendOutcome: 'failed' }); if ('reason' in outcome) onException(outcome.reason) }
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-05 · COS-605 · referral handoff preparation</p><h2>Prepare referral package</h2><p>Asha Mehta · SYNTHETIC CASE · direction: day-care referral · report SYN-DR-6001 v2</p></div><span className="state-badge">Referral Created</span></header><div className="screen-grid"><div><WorkflowStatus state="Referral Created" owner="Synthetic Referral Coordinator · operational package owner" next={routed ? 'Await receiving-team response. No acceptance has been recorded.' : 'Complete package requirements, then route to the receiving team'} ageDue="Package routing is pending." /><section className="evidence-panel handoff-context-panel"><p className="panel-label">Referral source · read only</p><h3>Referral source and approvals</h3><dl><div><dt>Direction</dt><dd>Day-care referral · Clinic physician evidence: SYN-DIR-602-01</dd></div><div><dt>Current acknowledged report</dt><dd>SYN-DR-6001 v2 · source record remains read-only</dd></div><div><dt>Package version</dt><dd>SYN-RP-1001 v1 · internal operational artefact</dd></div><div><dt>Routing authority</dt><dd>Referral Coordinator routes the package; Clinic physician separately approves applicable clinical content.</dd></div></dl><p className="scenario-boundary">Routing records a send attempt only; receiving-team acceptance remains separate.</p></section><section className="evidence-panel referral-panel"><p className="panel-label">Handoff package and routing gate</p><h3>Referral Coordinator review</h3><section className="routing-requirements" aria-labelledby="routing-requirements-title"><h4 id="routing-requirements-title">Package checklist</h4><ul>{routingRequirements.map((requirement) => <li className={requirement.complete ? 'complete' : 'blocked'} key={requirement.label}><strong>{requirement.label}</strong><span>{requirement.value}</span></li>)}</ul></section><label className="evidence-input">Destination<input value={destination} onChange={(event) => setDestination(event.target.value)} disabled={routed} placeholder="Enter receiving destination" /></label><label className="check-label"><input checked={requiredFieldsComplete} disabled={routed} type="checkbox" onChange={(event) => setRequiredFieldsComplete(event.target.checked)} />Required package fields are complete and reviewed</label><label className="check-label"><input checked={clinicalContentApplicable} disabled={routed} type="checkbox" onChange={(event) => setClinicalContentApplicable(event.target.checked)} />Clinical content approval is applicable</label>{clinicalContentApplicable && <label className="evidence-input">Clinic physician clinical-content approval<input value={clinicalApprovalId} onChange={(event) => setClinicalApprovalId(event.target.value)} disabled={routed} placeholder="Enter approval evidence ID" /></label>}<div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready to route' : 'Routing remains blocked'}</strong><span>{readinessMessage}</span></div>{routeResult ? <><div className="status-panel" role="status"><strong>Package and send-attempt evidence recorded</strong><span>{routeResult.packageEvent} · {routeResult.routeEvent} · sender: Synthetic Referral Coordinator · recorded at {routeResult.routedAt} · destination: {destination}. State remains Referral Created pending a receiving-team response.</span></div><p className="scenario-boundary">Routing is recorded for this screen. Receiving acceptance remains a separate decision.</p><section className="viewer-navigation-panel compact" aria-label="Portfolio walkthrough"><p className="panel-label">Portfolio walkthrough</p><button className="secondary-action" type="button" onClick={onViewNext}>Open receiving response</button></section></> : <div className="action-group"><button className="primary-action" disabled={!readiness.allowed} type="button" onClick={routePackage}>Route referral package</button><button className="secondary-action" type="button" onClick={showSendFailure}>Show represented send failure</button></div>}</section></div><JourneyRail phase="Handoff preparation" next="An explicit Referral Coordinator route is required before the receiving team can respond." /></div></section>
}

function ReceivingResponseScreen({ onException, onViewNext }: { onException: (condition: string) => void; onViewNext: (screenId: ScreenId) => void }) {
  const [decisionActor, setDecisionActor] = useState('')
  const [recordingActorRole, setRecordingActorRole] = useState('')
  const [recordingSource, setRecordingSource] = useState('')
  const [response, setResponse] = useState('')
  const [destination, setDestination] = useState('')
  const [timeframe, setTimeframe] = useState('')
  const [rejectionReason, setRejectionReason] = useState('')
  const [confirmed, setConfirmed] = useState(false)
  const [result, setResult] = useState<Extract<ReturnType<typeof evaluateReceivingResponse>, { allowed: true }> | null>(null)
  const responseInput = { currentState: 'Referral Created', packageId: 'SYN-RP-1001 v1', sendReference: 'SYN-SEND-1001', decisionActorRole: 'Receiving team', decisionActor, recordingActorRole, recordingSource, response, destination, timeframe, rejectionReason, confirmationId: confirmed ? 'SYN-CONFIRM-1002' : '', responseId: 'SYN-RESP-1001', alreadyRecorded: Boolean(result) }
  const readiness = evaluateReceivingResponse({ ...responseInput, alreadyRecorded: false })
  function recordResponse() { const outcome = evaluateReceivingResponse(responseInput); if ('reason' in outcome) { onException(outcome.reason); return }; setResult(outcome) }
  const nextOwner = result?.stateAfter === 'Referral Rejected' ? 'Clinic physician · new direction owner' : result?.stateAfter === 'Referral Accepted' ? 'Care Coordinator · next-step evidence owner' : 'Synthetic receiving team · response owner'
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-06 · COS-606 · receiving response</p><h2>Record referral response</h2><p>Asha Mehta · SYNTHETIC CASE · routed package SYN-RP-1001 v1</p></div><span className="state-badge">{result?.stateAfter ?? 'Referral Created'}</span></header><div className="screen-grid"><div><WorkflowStatus state={result?.stateAfter ?? 'Referral Created'} owner={nextOwner} next={result?.nextAction ?? 'Choose Accept or Reject and record the receiving-team decision'} ageDue="Awaiting a receiving-team response." /><section className="evidence-panel receiving-context-panel"><p className="panel-label">Routed package evidence · read only</p><h3>Referral package</h3><dl><div><dt>Package / send reference</dt><dd>SYN-RP-1001 v1 · SYN-SEND-1001</dd></div><div><dt>Routed destination</dt><dd>Synthetic Day-care Unit</dd></div><div><dt>Decision authority</dt><dd>Receiving team decides acceptance or rejection.</dd></div><div><dt>Recording boundary</dt><dd>Referral Coordinator may record received evidence, but cannot decide on the receiving team’s behalf.</dd></div></dl><p className="scenario-boundary">Package send is not receiving acceptance or specialist review. Acceptance, if recorded, still does not confirm the next step.</p></section><section className="evidence-panel receiving-panel"><p className="panel-label">Human receiving-team decision</p><h3>Response evidence</h3><p className="role-boundary">Name the receiving-team decision actor separately from the person who records the evidence. A source is required when the Referral Coordinator records a received response.</p><label className="evidence-input">Receiving-team decision actor<input disabled={Boolean(result)} value={decisionActor} onChange={(event) => setDecisionActor(event.target.value)} placeholder="Enter receiving-team decision actor" /></label><label className="evidence-input">Recording actor<select disabled={Boolean(result)} value={recordingActorRole} onChange={(event) => setRecordingActorRole(event.target.value)}><option value="">Select recording actor</option><option value="Receiving team">Receiving team</option><option value="Referral Coordinator">Referral Coordinator</option></select></label>{recordingActorRole === 'Referral Coordinator' && <label className="evidence-input">Received-response source<input disabled={Boolean(result)} value={recordingSource} onChange={(event) => setRecordingSource(event.target.value)} placeholder="Enter the receiving-team response source" /></label>}<fieldset className="response-options" disabled={Boolean(result)}><legend>Select the formal receiving-team response</legend><label><input checked={response === 'accept'} name="response" type="radio" onChange={() => setResponse('accept')} /><span className="response-option-copy"><strong>Accept</strong><span>Records Referral Accepted. Next-step confirmation remains a separate Care Coordinator action.</span></span></label><label><input checked={response === 'reject'} name="response" type="radio" onChange={() => setResponse('reject')} /><span className="response-option-copy"><strong>Reject</strong><span>Records Referral Rejected and returns visible work to a Clinic physician for a new direction. No replacement referral is created.</span></span></label></fieldset>{response === 'accept' && <div className="response-grid"><label>Receiving destination<input value={destination} onChange={(event) => setDestination(event.target.value)} disabled={Boolean(result)} /></label><label>Acceptance timeframe<input value={timeframe} onChange={(event) => setTimeframe(event.target.value)} disabled={Boolean(result)} /></label></div>}{response === 'reject' && <label className="evidence-input">Rejection reason<input value={rejectionReason} onChange={(event) => setRejectionReason(event.target.value)} disabled={Boolean(result)} /></label>}<label className="check-label confirmation"><input checked={confirmed} disabled={Boolean(result)} type="checkbox" onChange={(event) => setConfirmed(event.target.checked)} />I confirm the selected response, receiving-team decision actor and response evidence.</label><div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready to record' : 'Response remains pending'}</strong><span>{readiness.allowed ? 'EVT-14 will record the human response. Acceptance does not confirm the next step; rejection does not create an alternative referral.' : readiness.reason}</span></div>{result ? <><div className="status-panel" role="status"><strong>Receiving response recorded: {result.stateAfter}</strong><span>{result.auditEvent} · decision actor: {decisionActor} · recording actor: {recordingActorRole} · next owner: {nextOwner}. {result.nextAction}</span></div><p className="scenario-boundary">The response is recorded for this screen. The next action remains a separate human task.</p><section className="viewer-navigation-panel compact" aria-label="Portfolio walkthrough"><p className="panel-label">Portfolio walkthrough</p><button className="secondary-action" type="button" onClick={() => onViewNext(result.stateAfter === 'Referral Accepted' ? 'SCR-10' : 'SCR-04')}>{result.stateAfter === 'Referral Accepted' ? 'Open next-step review' : 'Return to follow-up planning'}</button></section></> : <button className="primary-action" disabled={!readiness.allowed} type="button" onClick={recordResponse}>Record receiving response</button>}</section></div><JourneyRail phase="Receiving response" next="Confirm accountable follow-up only after the applicable evidence exists." /></div></section>
}

function AiDraftReviewScreen({ onReturn }: { onReturn: (screenId: ScreenId) => void }) {
  const [capabilityId, setCapabilityId] = useState('AI-01')
  const [reviewerRole, setReviewerRole] = useState('')
  const [draftStatus, setDraftStatus] = useState('generated')
  const [disposition, setDisposition] = useState('')
  const [correctionNote, setCorrectionNote] = useState('')
  const [result, setResult] = useState<Extract<ReturnType<typeof evaluateAiDraftReview>, { allowed: true }> | null>(null)
  const [recordedAt, setRecordedAt] = useState<string | null>(null)
  const draft = AI_DRAFTS[capabilityId]
  const manualRoute = capabilityId === 'AI-01' ? 'SCR-03' : 'SCR-05'
  const callingWorkflow = capabilityId === 'AI-01' ? 'Source-based result review' : 'Human-approved referral handoff preparation'
  const manualRouteLabel = capabilityId === 'AI-01' ? 'Return to source-based result review' : 'Return to referral handoff preparation'
  const acceptanceDisposition = capabilityId === 'AI-01' ? 'accepted_for_orientation' : 'accepted_for_use'
  const acceptanceLabel = capabilityId === 'AI-01' ? 'Accept for orientation' : 'Accept for use'
  const reviewInput = { capabilityId, reviewerRole, reportVersion: '2', directionEvidence: capabilityId === 'AI-02' ? 'SYN-DIR-602-01' : '', draftStatus, sourceLinksComplete: true, disposition, correctionNote }
  const readiness = evaluateAiDraftReview(reviewInput)
  function changeCapability(nextCapability: string) { setCapabilityId(nextCapability); setReviewerRole(''); setDraftStatus('generated'); setDisposition(''); setCorrectionNote(''); setRecordedAt(null); setResult(null) }
  function recordDisposition() { const outcome = evaluateAiDraftReview(reviewInput); if ('reason' in outcome) return; setRecordedAt(new Date().toISOString()); setResult(outcome) }
  return <section className="workspace-screen ai-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-08 · COS-608 · optional AI draft review</p><h2>Review optional assistance against source evidence</h2><p>Asha Mehta · SYNTHETIC CASE · AI output is not source truth or a workflow decision</p></div><span className="state-badge">No canonical state change</span></header><div className="screen-grid"><div><WorkflowStatus state="Human workflow remains active" owner="Authorised human reviewer" next={result ? `${manualRouteLabel}; continue manually` : 'Review source context and uncertainty before considering the optional draft'} ageDue="The AI assist is optional. Its failure cannot block source-based work." /><section className="evidence-panel ai-source-panel"><p className="panel-label">Source context and manual fallback · read only</p><h3>Evidence before optional assistance</h3><fieldset className="response-options"><legend>Approved synthetic assist</legend><label><input checked={capabilityId === 'AI-01'} name="capability" type="radio" onChange={() => changeCapability('AI-01')} /><span className="response-option-copy"><strong>AI-01 · orientation draft</strong><span>Supports source-linked orientation only; it does not change clinical review.</span></span></label><label><input checked={capabilityId === 'AI-02'} name="capability" type="radio" onChange={() => changeCapability('AI-02')} /><span className="response-option-copy"><strong>AI-02 · handoff draft</strong><span>Supports post-approval handoff context only; package review and routing remain human-owned.</span></span></label></fieldset><dl><div><dt>Calling workflow</dt><dd>{callingWorkflow}</dd></div><div><dt>Source references / versions</dt><dd>{draft.sourceLinks.join(' · ')}</dd></div><div><dt>Evidence status</dt><dd>Approved synthetic source links represented · current report version 2 required by the existing controller.</dd></div><div><dt>Uncertainty</dt><dd>{draft.uncertainty}</dd></div><div><dt>Manual fallback</dt><dd>{manualRouteLabel}. This remains available if the draft is stale, unavailable, unsupported, rejected or discarded.</dd></div></dl><p className="ai-boundary">AI may draft orientation or operational context only. It cannot diagnose, acknowledge, choose direction, approve, route, accept, reject, confirm or close work.</p></section><section className="evidence-panel ai-draft-panel"><p className="panel-label">AI-generated draft · requires human review</p><h3>{draft.draftId} · {draftStatus}</h3><p>{draft.text}</p><dl><div><dt>Generated time</dt><dd>{draft.generatedAt}</dd></div><div><dt>Represented output status</dt><dd>{draftStatus}</dd></div><div><dt>Workflow boundary</dt><dd>Draft review can record EVT-20 only; no canonical workflow state changes.</dd></div></dl><fieldset className="response-options"><legend>Represented draft status</legend><label><input checked={draftStatus === 'generated'} name="draft-status" type="radio" onChange={() => setDraftStatus('generated')} />Generated and source-linked</label><label><input checked={draftStatus === 'unavailable'} name="draft-status" type="radio" onChange={() => setDraftStatus('unavailable')} />Unavailable</label><label><input checked={draftStatus === 'stale'} name="draft-status" type="radio" onChange={() => setDraftStatus('stale')} />Stale source/input</label></fieldset></section><section className="evidence-panel human-disposition-panel"><p className="panel-label">Authorised human disposition</p><h3>Record a human review outcome</h3><p>Choose the disposition that reflects the human review. No option is preselected or preferred.</p><label className="evidence-input">Authorised reviewer role<select value={reviewerRole} onChange={(event) => setReviewerRole(event.target.value)}><option value="">Select reviewer role</option>{capabilityId === 'AI-01' ? <><option value="Clinic physician">Clinic physician</option><option value="Care Coordinator">Care Coordinator</option></> : <option value="Referral Coordinator">Referral Coordinator</option>}</select></label><fieldset className="response-options ai-disposition-options"><legend>Select one human disposition</legend><label><input checked={disposition === acceptanceDisposition} name="disposition" type="radio" onChange={() => setDisposition(acceptanceDisposition)} /><span className="response-option-copy"><strong>{acceptanceLabel}</strong><span>Use the draft only as approved optional assistance.</span></span></label><label><input checked={disposition === 'corrected'} name="disposition" type="radio" onChange={() => setDisposition('corrected')} /><span className="response-option-copy"><strong>Correct</strong><span>Record a human correction before continuing manually.</span></span></label><label><input checked={disposition === 'rejected'} name="disposition" type="radio" onChange={() => setDisposition('rejected')} /><span className="response-option-copy"><strong>Reject</strong><span>Do not use the draft; continue through the source-based workflow.</span></span></label><label><input checked={disposition === 'discarded'} name="disposition" type="radio" onChange={() => setDisposition('discarded')} /><span className="response-option-copy"><strong>Discard</strong><span>Set aside the draft and continue manually.</span></span></label></fieldset>{disposition === 'corrected' && <label className="evidence-input">Correction note<input value={correctionNote} onChange={(event) => setCorrectionNote(event.target.value)} placeholder="Record the human correction" /></label>}<div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready to record human disposition' : 'Manual workflow remains available'}</strong><span>{readiness.allowed ? 'EVT-20 will record provenance and disposition only. The human must continue through the normal workflow.' : readiness.reason}</span></div>{result ? <div className="status-panel" role="status"><strong>Human disposition recorded: {result.disposition}</strong><span>{result.auditEvent} · reviewer: {reviewerRole} · local display time: {recordedAt} · sources: {draft.sourceLinks.join(' · ')}. No canonical state changed.</span><span>The local display time is not persisted audit evidence. Use the manual route to continue.</span><button className="secondary-action" type="button" onClick={() => onReturn(result.manualRoute as ScreenId)}>{manualRouteLabel}</button></div> : <div className="action-group"><button className="primary-action" disabled={!readiness.allowed} type="button" onClick={recordDisposition}>Record human disposition</button><button className="secondary-action" type="button" onClick={() => onReturn(manualRoute as ScreenId)}>Continue manually without AI</button></div>}</section></div><JourneyRail phase="Optional assistance" next="Manual source-based workflow remains available regardless of AI output." /></div></section>
}

function AuditTraceScreen() {
  const [category, setCategory] = useState('all')
  const entries = getAuditEntries(category)
  const filterLabel = category === 'all' ? 'All evidence' : category
  return <section className="workspace-screen audit-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-09 · COS-609 · audit and trace</p><h2>Review attributable workflow evidence</h2><p>Asha Mehta · SYNTHETIC CASE · representative append-oriented history · read only</p></div><span className="state-badge">No workflow action available</span></header><WorkflowStatus state="Audit evidence available" owner="Governance and authorised operational reviewers" next="Review evidence; missing or failed evidence remains a visible defect" ageDue="This screen cannot edit history, correct evidence or advance workflow." /><section className="evidence-panel audit-controls"><p className="panel-label">Read-only trace filter</p><label className="evidence-input">Evidence category<select value={category} onChange={(event) => setCategory(event.target.value)}><option value="all">All evidence</option><option value="source">Source evidence</option><option value="human decision">Human decisions</option><option value="workflow">Workflow evidence</option><option value="exception">Exceptions</option><option value="recovery">Recovery</option><option value="AI disposition">AI dispositions</option></select></label><p className="audit-filter-result" role="status"><strong>Active filter: {filterLabel}</strong><span>{entries.length} represented {entries.length === 1 ? 'entry' : 'entries'} shown</span></p><p>This is representative synthetic history, not a live session audit log. Viewing or acting on another demonstration screen does not append an entry here.</p></section><div className="audit-table-wrap"><table><caption>Chronological synthetic audit evidence · times include timezone offsets</caption><thead><tr><th scope="col">Time (timezone)</th><th scope="col">Event ID / outcome</th><th scope="col">Actor or source</th><th scope="col">Source / version reference</th><th scope="col">Category</th></tr></thead><tbody>{entries.length ? entries.map((entry) => <tr key={entry.id}><td data-label="Time (timezone)">{entry.timestamp}</td><td data-label="Event ID / outcome"><strong>{entry.event}</strong><span>{entry.outcome}</span></td><td data-label="Actor or source">{entry.actor}</td><td data-label="Source / version reference">{entry.reference}</td><td data-label="Category"><span className="audit-category">{entry.category}</span></td></tr>) : <tr><td className="audit-empty-state" colSpan={5} role="status">No represented audit entries match the active filter. Choose another approved evidence category.</td></tr>}</tbody></table></div><div className="status-panel"><strong>Audit trace is read-only and representative</strong><span>Corrections and recoveries must append linked evidence; a failed action is never shown as success. This screen contains no linked-evidence, correction-chain, destructive correction or workflow controls.</span></div></section>
}

function NextStepConfirmationScreen({ onException }: { onException: (condition: string) => void }) {
  const [evidence, setEvidence] = useState({ owner: '', destination: '', timeframe: '', communicationApproval: '', authorisedSender: '', channel: '', deliveryEvidence: '', explicitConfirmationEvidence: '' })
  const [confirmed, setConfirmed] = useState(false)
  const [closed, setClosed] = useState(false)
  const updateEvidence = (field: keyof typeof evidence, value: string) => setEvidence((current) => ({ ...current, [field]: value }))
  const sharedInput = { actorRole: 'Care Coordinator', reportVersion: '2', directionEvidence: 'SYN-DIR-602-01', handoffStatus: 'completed', receivingResponse: 'accepted', explicitConfirmationRequired: true, hasSafetyBlockingException: false, ...evidence }
  const confirmationReadiness = evaluateNextStepConfirmation({ ...sharedInput, currentState: 'Referral Accepted', confirmationId: 'SYN-CONFIRM-1003', alreadyConfirmed: false })
  const closureReadiness = evaluateScopedClosure({ ...sharedInput, currentState: 'Next Step Confirmed', closureId: 'SYN-CLOSE-1001', closureEvidenceVersion: 'SYN-CLOSURE-EVIDENCE-v1', closer: 'Synthetic Care Coordinator', closureTime: '2026-07-26T14:00:00+05:30', alreadyClosed: false })
  const verificationEvidence = [
    { label: 'Next-step owner', owner: 'Care Coordinator', source: 'Care Coordinator verification input', value: evidence.owner },
    { label: 'Destination / team', owner: 'Care Coordinator', source: 'Care Coordinator verification input', value: evidence.destination },
    { label: 'Timeframe', owner: 'Care Coordinator', source: 'Care Coordinator verification input', value: evidence.timeframe },
    { label: 'Communication approval', owner: 'Authorised communication owner', source: 'Approved communication reference', value: evidence.communicationApproval },
    { label: 'Authorised sender', owner: 'Care Coordinator', source: 'Named authorised-sender evidence', value: evidence.authorisedSender },
    { label: 'Channel', owner: 'Care Coordinator', source: 'Named communication channel', value: evidence.channel },
    { label: 'Delivery evidence', owner: 'Delivery evidence source', source: 'Delivery evidence', value: evidence.deliveryEvidence },
    { label: 'Patient/caregiver confirmation', owner: 'Patient/caregiver confirmation source', source: 'Explicit confirmation evidence', value: evidence.explicitConfirmationEvidence },
  ]
  function recordConfirmation() { const outcome = evaluateNextStepConfirmation({ ...sharedInput, currentState: 'Referral Accepted', confirmationId: 'SYN-CONFIRM-1003', alreadyConfirmed: confirmed }); if ('reason' in outcome) { onException(outcome.reason); return }; setConfirmed(true) }
  function recordClosure() { const outcome = evaluateScopedClosure({ ...sharedInput, currentState: 'Next Step Confirmed', closureId: 'SYN-CLOSE-1001', closureEvidenceVersion: 'SYN-CLOSURE-EVIDENCE-v1', closer: 'Synthetic Care Coordinator', closureTime: '2026-07-26T14:00:00+05:30', alreadyClosed: closed }); if ('reason' in outcome) { onException(outcome.reason); return }; setClosed(true) }
  const state = closed ? 'Episode Completed' : confirmed ? 'Next Step Confirmed' : 'Referral Accepted'
  return <section className="workspace-screen closure-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-10 · COS-610 · next-step confirmation and scoped closure</p><h2>Confirm the next care step</h2><p>Asha Mehta · SYNTHETIC CASE · day-care referral · current report SYN-DR-6001 v2</p></div><span className="state-badge">{state}</span></header><div className="screen-grid"><div><WorkflowStatus state={state} owner="Care Coordinator records verification and closure evidence" next={closed ? 'No further diagnostic-closure action is available.' : confirmed ? 'Review closure evidence and record scoped completion separately.' : 'Verify applicable human-owned evidence before recording Next Step Confirmed.'} ageDue="No automatic confirmation or closure is available." /><section className="evidence-panel"><p className="panel-label">Referral evidence · read only</p><h3>Referral and response evidence</h3><dl><div><dt>Human direction</dt><dd>Day-care referral · Clinic physician · SYN-DIR-602-01 · current report v2</dd></div><div><dt>Handoff / response</dt><dd>Completed handoff SYN-RP-1001 v1 · receiving-team acceptance EVT-14</dd></div><div><dt>Exception check</dt><dd>No safety-blocking exception represented for this local scenario.</dd></div></dl><p className="scenario-boundary">Approved synthetic referral and response evidence is shown for this review.</p></section><section className="evidence-panel confirmation-readiness-summary"><p className="panel-label">Evidence readiness · read only</p><h3>Check required evidence</h3><ul>{verificationEvidence.map((item) => <li key={item.label}><div><strong>{item.label}</strong><span>{item.value || 'Not recorded'}</span></div><dl><div><dt>Accountable owner</dt><dd>{item.owner}</dd></div><div><dt>Source / reference</dt><dd>{item.source}</dd></div></dl><span className={item.value ? 'evidence-status complete' : 'evidence-status incomplete'}>{item.value ? 'Complete' : 'Incomplete'}</span></li>)}</ul></section><section className="evidence-panel closure-evidence-panel"><p className="panel-label">Care Coordinator verification</p><h3>Verification details</h3><div className="confirmation-grid"><label>Next-step owner<input disabled={confirmed || closed} value={evidence.owner} onChange={(event) => updateEvidence('owner', event.target.value)} /></label><label>Destination / team<input disabled={confirmed || closed} value={evidence.destination} onChange={(event) => updateEvidence('destination', event.target.value)} /></label><label>Timeframe<input disabled={confirmed || closed} value={evidence.timeframe} onChange={(event) => updateEvidence('timeframe', event.target.value)} /></label><label>Approved communication reference<input disabled={confirmed || closed} value={evidence.communicationApproval} onChange={(event) => updateEvidence('communicationApproval', event.target.value)} /></label><label>Authorised sender<input disabled={confirmed || closed} value={evidence.authorisedSender} onChange={(event) => updateEvidence('authorisedSender', event.target.value)} /></label><label>Channel<input disabled={confirmed || closed} value={evidence.channel} onChange={(event) => updateEvidence('channel', event.target.value)} /></label><label>Delivery evidence · EVT-17<input disabled={confirmed || closed} value={evidence.deliveryEvidence} onChange={(event) => updateEvidence('deliveryEvidence', event.target.value)} /></label><label>Explicit patient/caregiver confirmation · EVT-18<input disabled={confirmed || closed} value={evidence.explicitConfirmationEvidence} onChange={(event) => updateEvidence('explicitConfirmationEvidence', event.target.value)} /></label></div><p className="closure-boundary">Delivery and explicit confirmation are separate evidence. The Care Coordinator verifies them but cannot supply the clinical direction, receiving-team response, or patient confirmation.</p>{!confirmed && <aside className="closure-next" role="note"><strong>Then: scoped closure</strong><span>Scoped closure remains unavailable until a Care Coordinator has separately recorded Next Step Confirmed. It is not inferred from this evidence.</span></aside>}{!confirmed ? <><div className={confirmationReadiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{confirmationReadiness.allowed ? 'Ready for human-recorded next-step confirmation' : 'Next-step confirmation remains blocked'}</strong><span>{confirmationReadiness.allowed ? 'Care Coordinator, action, evidence and recorded timestamp are shown before EVT-16 is recorded.' : confirmationReadiness.reason}</span></div><div className="action-group"><button className="primary-action" disabled={!confirmationReadiness.allowed} type="button" onClick={recordConfirmation}>Record Next Step Confirmed</button><button className="secondary-action" type="button" onClick={() => onException('Missing handoff or confirmation evidence')}>Show safe exception route</button></div></> : <div className="status-panel" role="status"><strong>Next Step Confirmed recorded</strong><span>EVT-16 · Care Coordinator · synthetic timestamp 2026-07-26T14:00:00+05:30. This confirmation does not close the diagnostic workflow.</span></div>}{confirmed && !closed && <div className="closure-action"><h3>Scoped closure</h3><p>Closure is a second human-owned action. It is not inferred from the confirmation, delivery or any AI activity.</p><div className={closureReadiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{closureReadiness.allowed ? 'Ready for scoped diagnostic-closure workflow completion' : 'Scoped closure remains blocked'}</strong><span>{closureReadiness.allowed ? 'The Care Coordinator may now record EVT-22 with the complete applicable evidence.' : closureReadiness.reason}</span></div><button className="primary-action" disabled={!closureReadiness.allowed} type="button" onClick={recordClosure}>Record scoped Episode Completed</button></div>}{closed && <div className="status-panel" role="status"><strong>Episode Completed · diagnostic-closure workflow completion</strong><span>EVT-22 · Care Coordinator · synthetic timestamp 2026-07-26T14:00:00+05:30. This does not claim that all care is complete.</span></div>}</section></div><JourneyRail phase={closed ? 'Diagnostic-closure workflow completed' : confirmed ? 'Next step confirmed' : 'Evidence verification'} next={closed ? 'Diagnostic-closure workflow complete; broader care continues outside this scope.' : confirmed ? 'Review the separate scoped-closure evidence and action.' : 'Complete the applicable evidence checks before the next separate human action.'} /></div></section>
}

function ExceptionScreen({ detail, onReturn }: { detail: Extract<ReturnType<typeof resolveSimulatedLaunch>, { kind: 'exception' }> | null; onReturn: (state: string) => void }) {
  const initialId = EXCEPTION_PROFILES.find((item) => item.condition === detail?.condition)?.id ?? 'result-incomplete'
  const protectedContextHidden = Boolean(detail && ['Authorisation denied', 'Integration Unavailable', 'Patient Match Failed'].includes(detail.condition))
  const [selectedId, setSelectedId] = useState(initialId)
  const [actorRole, setActorRole] = useState('')
  const [resolutionEvidence, setResolutionEvidence] = useState('')
  const [verificationOutcome, setVerificationOutcome] = useState('')
  const [resolution, setResolution] = useState<Extract<ReturnType<typeof evaluateExceptionResolution>, { allowed: true }> | null>(null)
  const profile = EXCEPTION_PROFILES.find((item) => item.id === selectedId)!
  const readiness = evaluateExceptionResolution({ exceptionId: selectedId, actorRole, resolutionEvidence, verificationOutcome, alreadyResolved: false })
  function selectException(id: string) { setSelectedId(id); setActorRole(''); setResolutionEvidence(''); setVerificationOutcome(''); setResolution(null) }
  function recordResolution() { const outcome = evaluateExceptionResolution({ exceptionId: selectedId, actorRole, resolutionEvidence, verificationOutcome, alreadyResolved: Boolean(resolution) }); if ('reason' in outcome) return; setResolution(outcome) }
  const returnDestination = profile.lastVerifiedState === 'Clinical Review Pending' ? 'assigned clinician review' : profile.lastVerifiedState === 'Referral Created' ? 'referral handoff preparation' : profile.lastVerifiedState === 'Referral Accepted' || profile.lastVerifiedState === 'Next Step Confirmed' ? 'next-step confirmation' : 'episode overview'
  return <section className="workspace-screen exception-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-07 · COS-607 · exception queue and detail</p><h2>Resolve exception work safely</h2><p>{protectedContextHidden ? 'Protected patient and episode context remains hidden until accountable recovery and re-verification.' : 'Represented workflow failures remain visible, owned and recoverable without silently advancing or closing the episode.'}</p></div><span className="state-badge">{resolution ? 'Resolution recorded' : 'Exception open'}</span></header><div className="screen-grid"><div>{protectedContextHidden && <div className="status-panel protected-context-notice" role="status"><strong>Protected context remains hidden</strong><span>Accountable recovery owner: {profile.owner}. {profile.safeAction}</span></div>}<WorkflowStatus state={resolution ? profile.lastVerifiedState : 'Exception open'} owner={profile.owner} next={resolution?.nextAction ?? profile.safeAction} ageDue="No automatic progression is available while this exception remains open." /><p className="scenario-boundary">{detail ? 'Received from a represented originating failure.' : 'Standalone demonstration profile: no live originating event or persisted episode state is implied.'} Viewing this queue does not grant resolution authority.</p><div className="exception-master-detail"><section className="exception-queue" aria-label="Open exception work"><p className="panel-label">Open exception work · {EXCEPTION_PROFILES.length} represented conditions</p><h3>Compare condition, affected work and owner</h3><p className="exception-queue-help">Choose one profile to inspect its exact recovery gate. Every represented condition remains <strong>Exception open</strong> until verified resolution is recorded.</p><div>{EXCEPTION_PROFILES.map((item) => { const selected = item.id === selectedId; return <button aria-controls="selected-exception-detail" aria-pressed={selected} className={selected ? 'exception-item selected' : 'exception-item'} key={item.id} type="button" onClick={() => selectException(item.id)}><span className="exception-item-heading"><strong>{item.condition}</strong>{selected && <span className="exception-selection-marker">Selected</span>}</span><span><b>Affected work:</b> {item.affectedWork}</span><span><b>Owner:</b> {item.owner}</span><span><b>Status:</b> Exception open</span></button> })}</div></section><section aria-labelledby="selected-exception-title" className="evidence-panel exception-detail-panel" id="selected-exception-detail"><p className="panel-label">Selected exception · {profile.auditEvent}</p><h3 id="selected-exception-title">{profile.condition}</h3><dl><div><dt>Affected work</dt><dd>{profile.affectedWork}</dd></div><div><dt>Accountable owner</dt><dd>{profile.owner}</dd></div><div><dt>Prohibited action</dt><dd>{profile.prohibitedAction}</dd></div><div><dt>Safe action</dt><dd>{profile.safeAction}</dd></div><div><dt>Safe-return condition</dt><dd>{profile.safeReturn}</dd></div><div><dt>Manual return destination</dt><dd>{returnDestination}</dd></div></dl>{resolution ? <div className="status-panel recovery-evidence" role="status"><strong>Verified resolution evidence appended</strong><span>{resolution.auditEvent} · recording actor: {actorRole} · evidence: {resolutionEvidence} · resulting last-verified state: {resolution.stateAfter}.</span><span>No original clinical, referral, financial or closure action was recreated. Return is a separate manual step.</span><button className="secondary-action" type="button" onClick={() => onReturn(resolution.stateAfter)}>Return manually to {returnDestination}</button></div> : <section className="recovery-form" aria-labelledby="recovery-form-title"><p className="panel-label">Approved recovery gate</p><h4 id="recovery-form-title">Evidence required before resolution</h4><ul className="recovery-requirements"><li><strong>Accountable role</strong><span>{profile.actorRole}</span></li><li><strong>Recovery evidence</strong><span>A source verification or recovery evidence ID must be recorded.</span></li><li><strong>Verification outcome</strong><span>The resolution must be explicitly verified; failed or unresolved work remains open.</span></li></ul><label className="evidence-input">Accountable resolution role<select value={actorRole} onChange={(event) => setActorRole(event.target.value)}><option value="">Select accountable role</option>{[...new Set(EXCEPTION_PROFILES.map((item) => item.actorRole))].map((role) => <option key={role} value={role}>{role}</option>)}</select></label><label className="evidence-input">Verified resolution evidence<input value={resolutionEvidence} onChange={(event) => setResolutionEvidence(event.target.value)} placeholder="Enter source verification or recovery evidence ID" /></label><fieldset className="response-options"><legend>Verification outcome</legend><label><input checked={verificationOutcome === 'verified'} name="verification" type="radio" onChange={() => setVerificationOutcome('verified')} />Verified resolution</label><label><input checked={verificationOutcome === 'failed'} name="verification" type="radio" onChange={() => setVerificationOutcome('failed')} />Resolution failed or remains unresolved</label></fieldset><div className={readiness.allowed ? 'readiness-panel ready' : 'readiness-panel'} role="status"><strong>{readiness.allowed ? 'Ready to record verified resolution' : 'Exception remains open'}</strong><span>{readiness.allowed ? 'EVT-21 will record recovery evidence only. It does not recreate a clinical, referral, financial or closure action.' : readiness.reason}</span></div><button className="primary-action" disabled={!readiness.allowed} type="button" onClick={recordResolution}>Record verified resolution</button></section>}</section></div></div>{protectedContextHidden ? <aside className="journey-rail protected-context-rail" aria-label="Access recovery context"><p className="panel-label">Access recovery</p><h3>Protected context unavailable</h3><p>No synthetic patient, encounter or episode detail is shown on this recovery route.</p><p className="journey-next"><strong>Accountable owner:</strong> {profile.owner}<br /><strong>Safe action:</strong> {profile.safeAction}</p></aside> : <JourneyRail phase="Journey paused: needs review" next={`After verified recovery, return manually to ${returnDestination}.`} />}</div></section>
}

function DirectionScreen({ onException, onViewNext }: { onException: (condition: string) => void; onViewNext: () => void }) {
  const [selectedDirection, setSelectedDirection] = useState('')
  const [evidenceReference, setEvidenceReference] = useState('')
  const [result, setResult] = useState<DirectionSuccess | null>(null)
  const [t08Confirmed, setT08Confirmed] = useState(false)
  const [t08Evidence, setT08Evidence] = useState({ owner: '', timeframe: '', nextTask: '', communicationEvidence: '' })
  const acknowledgementAudit = getAuditEntries().find((entry) => entry.event === 'EVT-10 result.acknowledgement.recorded')!
  const directionAudit = getAuditEntries().find((entry) => entry.event === 'EVT-11 care.direction.recorded')!
  const updateT08 = (field: keyof typeof t08Evidence, value: string) => setT08Evidence((current) => ({ ...current, [field]: value }))
  function recordDirection() { const outcome = evaluateFollowUpDirection({ actorRole: 'Clinic physician', currentState: 'Follow-up Decision Required', reportVersion: '2', selectedDirection, evidenceReference, directionId: 'SYN-DIR-602-01' }); if (!outcome.allowed) { onException(outcome.reason); return }; setResult(outcome) }
  function verifyT08() { const outcome = evaluateT08Verification({ actorRole: 'Care Coordinator', selectedDirection, ...t08Evidence, verificationId: 'SYN-T08-602-01' }); if (!outcome.allowed) { onException(outcome.reason); return }; setT08Confirmed(true) }
  const displayedState = t08Confirmed ? 'Next Step Confirmed' : result?.stateAfter ?? 'Follow-up Decision Required'
  return <section className="workspace-screen"><header className="workspace-header"><div><p className="eyebrow">SCR-04 · COS-604 · human-owned follow-up direction</p><h2>Choose a follow-up plan</h2><p>Asha Mehta · SYNTHETIC CASE · acknowledged report SYN-DR-6001 v2</p></div><span className="state-badge">{displayedState}</span></header><div className="screen-grid"><div><WorkflowStatus state={displayedState} owner={t08Confirmed ? 'Care Coordinator · confirmation owner' : 'Synthetic Clinic Physician · clinical direction owner'} next={result?.nextAction ?? 'Choose one plan and add its evidence'} /><section className="evidence-panel represented-context-panel"><p className="panel-label">Report context · read only</p><h3>SYN-DR-6001 · current v2</h3><dl><div><dt>Source status</dt><dd>amended · current version</dd></div><div><dt>Acknowledgement actor</dt><dd>{acknowledgementAudit.actor}</dd></div><div><dt>Acknowledgement time</dt><dd>{acknowledgementAudit.timestamp}</dd></div><div><dt>Workflow state</dt><dd>Follow-up Decision Required</dd></div></dl><p className="scenario-boundary">Current report and acknowledgement evidence are shown for this synthetic case.</p></section><section className="evidence-panel direction-panel"><p className="panel-label">Human decision boundary</p><h3>Follow-up plan</h3><p>Choose the appropriate plan and record the supporting evidence. No option is recommended or preselected.</p><fieldset className="direction-options" disabled={Boolean(result)}><legend>Select one approved direction</legend>{DIRECTION_OPTIONS.map((direction) => <label key={direction.value}><input checked={selectedDirection === direction.value} name="direction" type="radio" onChange={() => setSelectedDirection(direction.value)} /><span className="direction-option-copy"><strong>{direction.label}</strong><span>Immediate workflow consequence: {direction.consequence}</span></span></label>)}</fieldset><label className="evidence-input">Direction rationale / evidence reference<input value={evidenceReference} onChange={(event) => setEvidenceReference(event.target.value)} placeholder="For example: SYN-DR-6001 v2" disabled={Boolean(result)} /></label>{result ? <><div className="status-panel" role="status"><strong>Direction recorded: {selectedDirection}</strong><span>Actor: {directionAudit.actor} · recorded at {directionAudit.timestamp} · {result.auditEvent}. {result.requiresCoordinatorVerification ? 'Care Coordinator T08 verification is required before the next step is confirmed.' : result.nextAction}</span></div><p className="scenario-boundary">Saved for this screen. Continue below to review the referral package; no data is transferred automatically.</p><section className="viewer-navigation-panel compact" aria-label="Portfolio walkthrough"><p className="panel-label">Portfolio walkthrough</p><button className="secondary-action" type="button" onClick={onViewNext}>Open referral handoff</button></section></> : <div className="action-group"><button className="primary-action" type="button" onClick={recordDirection}>Save follow-up plan</button><button className="secondary-action" type="button" onClick={() => onException('Current report version requires review')}>Show stale-version safe route</button></div>}</section>{result?.requiresCoordinatorVerification && <section className="evidence-panel t08-panel"><p className="panel-label">Separate operational confirmation</p><h3>Care Coordinator T08 verification</h3><p>This does not change the Clinic physician’s direction. Confirm the authorised operational evidence before recording Next Step Confirmed.</p><div className="t08-grid"><label>Named owner<input disabled={t08Confirmed} value={t08Evidence.owner} onChange={(event) => updateT08('owner', event.target.value)} /></label><label>Timeframe<input disabled={t08Confirmed} value={t08Evidence.timeframe} onChange={(event) => updateT08('timeframe', event.target.value)} /></label><label>Next task<input disabled={t08Confirmed} value={t08Evidence.nextTask} onChange={(event) => updateT08('nextTask', event.target.value)} /></label><label>Applicable communication evidence<input disabled={t08Confirmed} value={t08Evidence.communicationEvidence} onChange={(event) => updateT08('communicationEvidence', event.target.value)} /></label></div>{t08Confirmed ? <div className="status-panel" role="status"><strong>Next Step Confirmed</strong><span>Care Coordinator verification recorded · EVT-16 next-step.confirmation.recorded. Direction remains clinic management.</span></div> : <button className="primary-action" type="button" onClick={verifyT08}>Verify T08 evidence and confirm next step</button>}</section>}</div><JourneyRail phase="Human direction" next={result?.nextAction ?? 'A human Clinic physician must choose and evidence the next direction.'} /></div></section>
}

export function App() {
  const [activeScreen, setActiveScreen] = useState<ScreenId>(screenFromHash); const [launchStatus, setLaunchStatus] = useState<'ready' | 'loading'>('ready'); const [authorised, setAuthorised] = useState(false); const [exception, setException] = useState<Extract<ReturnType<typeof resolveSimulatedLaunch>, { kind: 'exception' }> | null>(null); const [launchEstablished, setLaunchEstablished] = useState(false); const [session, setSession] = useState<SimulatedSession | null>(null)
  const orientationScreen = activeScreen === 'SCR-01' || activeScreen === 'SCR-02'
  useEffect(() => { const update = () => { const nextScreen = screenFromHash(); normalizeHash(nextScreen); setActiveScreen(nextScreen) }; update(); window.addEventListener('hashchange', update); return () => window.removeEventListener('hashchange', update) }, [])
  function requestNavigation(screenId: ScreenId) { if (screenId === activeScreen) return; setSession(sessionForScreen(screenId)); navigateTo(screenId) }
  function launch(outcome: 'authorised' | 'unavailable' = 'authorised') { setLaunchStatus('loading'); window.setTimeout(() => { const result = resolveSimulatedLaunch(fixture, outcome); setLaunchStatus('ready'); if (result.kind === 'exception') { setAuthorised(false); setLaunchEstablished(false); setSession(null); setException(result); navigateTo('SCR-07') } else { setAuthorised(true); setLaunchEstablished(true); setException(null); setSession({ displayName: 'Synthetic Care Coordinator', role: 'Care Coordinator' }); navigateTo('SCR-02') } }, 250) }
  function reset() { setAuthorised(false); setException(null); setLaunchEstablished(false); setSession(null); navigateTo('SCR-01') }
  function returnToLastVerifiedWork(state: string) { setException(null); if (state === 'Clinical Review Pending') requestNavigation('SCR-03'); else if (state === 'Referral Created') requestNavigation('SCR-05'); else if (state === 'Referral Accepted' || state === 'Next Step Confirmed') requestNavigation('SCR-10'); else requestNavigation('SCR-02') }
  function showException(condition: string) { setException({ kind: 'exception', condition, owner: 'Diagnostic operations', safeReturn: 'Resolve current evidence, then return to the authorised human workflow.', protectedContextAvailable: false }); navigateTo('SCR-07') }
  return <div className="app-shell" data-screen={activeScreen}><a className="skip-link" href="#prototype-content">Skip to workspace content</a><header className="topbar"><div className="brand-block"><span aria-hidden="true" className="brand-mark">C</span><div><p className="eyebrow">Diagnostic closure workspace</p><h1>ContinuumOS</h1></div></div><SessionIdentity activeScreen={activeScreen} launchEstablished={launchEstablished} session={session} /><p className="prototype-disclaimer">Portfolio prototype · synthetic data only</p></header><div className={`workspace${orientationScreen ? '' : ' task-workspace'}`}>{orientationScreen && <PrototypeJourneyNavigation activeScreen={activeScreen} onSelect={requestNavigation} orientationScreen />}{<main id="prototype-content" tabIndex={-1}>{!orientationScreen && <PrototypeJourneyNavigation activeScreen={activeScreen} onSelect={requestNavigation} orientationScreen={false} />}{activeScreen === 'SCR-01' && <Launch status={launchStatus} onLaunch={launch} />}{activeScreen === 'SCR-02' && <Workspace authorised={authorised} onException={() => launch('unavailable')} onViewNext={() => requestNavigation('SCR-03')} />}{activeScreen === 'SCR-03' && <ReviewScreen onException={showException} onViewNext={() => requestNavigation('SCR-04')} />}{activeScreen === 'SCR-04' && <DirectionScreen onException={showException} onViewNext={() => requestNavigation('SCR-05')} />}{activeScreen === 'SCR-05' && <ReferralScreen onException={showException} onViewNext={() => requestNavigation('SCR-06')} />}{activeScreen === 'SCR-06' && <ReceivingResponseScreen onException={showException} onViewNext={requestNavigation} />}{activeScreen === 'SCR-07' && <ExceptionScreen detail={exception} onReturn={returnToLastVerifiedWork} />}{activeScreen === 'SCR-08' && <AiDraftReviewScreen onReturn={requestNavigation} />}{activeScreen === 'SCR-09' && <AuditTraceScreen />}{activeScreen === 'SCR-10' && <NextStepConfirmationScreen onException={showException} />}</main>}</div></div>
}
